import React, { useState, useEffect, useCallback } from 'react';
import { Globe, RefreshCw, TrendingDown } from 'lucide-react';

interface Currency {
    code: string;
    name: string;
    flag: string;
    rateVsUSD: number; // units per 1 USD
}

// Tipos de cambio regionales vs USD (fuente estimada 2025)
const BASE_CURRENCIES: Omit<Currency, 'rateVsUSD'>[] = [
    { code: 'ARS', name: 'Peso Argentino', flag: '🇦🇷' },
    { code: 'BRL', name: 'Real Brasileño', flag: '🇧🇷' },
    { code: 'CLP', name: 'Peso Chileno', flag: '🇨🇱' },
    { code: 'UYU', name: 'Peso Uruguayo', flag: '🇺🇾' },
    { code: 'PEN', name: 'Sol Peruano', flag: '🇵🇪' },
    { code: 'COP', name: 'Peso Colombiano', flag: '🇨🇴' },
    { code: 'MXN', name: 'Peso Mexicano', flag: '🇲🇽' },
    { code: 'EUR', name: 'Euro', flag: '🇪🇺' },
];

const BASE_RATES: Record<string, number> = {
    ARS: 1200, BRL: 4.95, CLP: 925, UYU: 38.5,
    PEN: 3.75, COP: 4050, MXN: 17.2, EUR: 0.92,
};

type Mode = 'from' | 'to';

function addNoise(rate: number) {
    return rate * (1 + (Math.random() - 0.5) * 0.01);
}

export const MultiCurrencyComparator: React.FC<{ blueRate?: number }> = ({ blueRate }) => {
    const [currencies, setCurrencies] = useState<Currency[]>([]);
    const [from, setFrom] = useState('ARS');
    const [to, setTo] = useState('BRL');
    const [amount, setAmount] = useState('10000');
    const [selecting, setSelecting] = useState<Mode | null>(null);

    const load = useCallback(() => {
        const data: Currency[] = BASE_CURRENCIES.map(c => ({
            ...c,
            rateVsUSD: c.code === 'ARS'
                ? (blueRate ?? BASE_RATES.ARS) * addNoise(1)
                : addNoise(BASE_RATES[c.code] ?? 1),
        }));
        setCurrencies(data);
    }, [blueRate]);

    useEffect(() => {
        load();
        const iv = setInterval(load, 60_000);
        return () => clearInterval(iv);
    }, [load]);

    const amountNum = parseFloat(amount.replace(/\D/g, '')) || 0;
    const fromRate = currencies.find(c => c.code === from)?.rateVsUSD ?? 1;
    const toRate = currencies.find(c => c.code === to)?.rateVsUSD ?? 1;
    const converted = amountNum / fromRate * toRate;
    const midRate = toRate / fromRate;

    const fmt = (n: number, c: string) => {
        if (n > 1000) return n.toLocaleString('es-AR', { maximumFractionDigits: 0 });
        if (n > 1) return n.toLocaleString('es-AR', { maximumFractionDigits: 2 });
        return n.toFixed(4);
    };

    const CurrencyPicker = ({ mode }: { mode: Mode }) => {
        const selected = mode === 'from' ? from : to;
        const setSelected = mode === 'from' ? setFrom : setTo;
        const curr = currencies.find(c => c.code === selected);

        return (
            <div className="relative">
                <button
                    onClick={() => setSelecting(selecting === mode ? null : mode)}
                    className="flex items-center gap-2 bg-white/10 hover:bg-white/15 border border-white/20 rounded-xl px-3 py-2.5 text-sm font-bold text-white transition-all w-full"
                >
                    <span className="text-xl">{curr?.flag}</span>
                    <span>{curr?.code}</span>
                    <span className="text-slate-500 font-normal text-xs ml-auto">{curr?.name}</span>
                </button>
                {selecting === mode && (
                    <div className="absolute top-full mt-1 left-0 z-50 w-full bg-[#0d1117] border border-white/10 rounded-xl shadow-2xl overflow-hidden">
                        {currencies.map(c => (
                            <button
                                key={c.code}
                                onClick={() => { setSelected(c.code); setSelecting(null); }}
                                className={`w-full flex items-center gap-2 px-3 py-2 text-xs hover:bg-white/10 transition-colors ${selected === c.code ? 'text-cyan-300 bg-white/5' : 'text-slate-300'}`}
                            >
                                <span>{c.flag}</span>
                                <span className="font-bold">{c.code}</span>
                                <span className="text-slate-500">{c.name}</span>
                                <span className="ml-auto font-mono text-slate-600">${c.rateVsUSD.toFixed(c.rateVsUSD > 100 ? 0 : 2)}/USD</span>
                            </button>
                        ))}
                    </div>
                )}
            </div>
        );
    };

    // ARS depreciation vs others
    const arsRate = currencies.find(c => c.code === 'ARS')?.rateVsUSD ?? 0;
    const START_ARS_2020 = 70;
    const depreciation = arsRate > 0 ? (((arsRate - START_ARS_2020) / START_ARS_2020) * 100).toFixed(0) : '0';

    return (
        <div className="glass-panel no-lift p-5" onClick={() => setSelecting(null)}>
            <div className="flex items-center gap-2 mb-4">
                <Globe size={14} className="text-sky-400" />
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest">Comparador Multi-moneda</h3>
            </div>

            {/* Amount input */}
            <div className="mb-3">
                <label className="text-[10px] text-slate-500 font-bold uppercase block mb-1">Importe</label>
                <input
                    type="text"
                    value={new Intl.NumberFormat('es-AR').format(amountNum)}
                    onChange={e => setAmount(e.target.value.replace(/\D/g, ''))}
                    onClick={e => e.stopPropagation()}
                    className="w-full bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-sm font-mono text-white focus:outline-none focus:border-sky-400/40 transition-colors"
                />
            </div>

            {/* Currency pickers */}
            <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-2 mb-4" onClick={e => e.stopPropagation()}>
                <CurrencyPicker mode="from" />
                <button
                    onClick={() => { const tmp = from; setFrom(to); setTo(tmp); }}
                    className="p-2 bg-white/10 hover:bg-white/15 rounded-full text-slate-400 hover:text-white border border-white/10 transition-colors"
                >
                    ⇄
                </button>
                <CurrencyPicker mode="to" />
            </div>

            {/* Result */}
            <div className="bg-sky-400/5 border border-sky-400/15 rounded-xl p-4 mb-4 text-center">
                <div className="text-[10px] text-slate-500 mb-1">
                    {amountNum.toLocaleString('es-AR')} {from} =
                </div>
                <div className="text-3xl font-black font-mono text-sky-300">
                    {fmt(converted, to)}
                </div>
                <div className="text-sm text-sky-400 font-bold">{to}</div>
                <div className="text-[10px] text-slate-600 mt-1">
                    Tipo de cambio: 1 {from} = {midRate.toFixed(4)} {to}
                </div>
            </div>

            {/* ARS depreciation */}
            <div className="flex items-center gap-2 p-2.5 rounded-lg bg-rose-400/5 border border-rose-400/15 text-[10px] text-rose-300">
                <TrendingDown size={12} className="flex-shrink-0" />
                <span>El ARS acumula ~<strong>{depreciation}%</strong> de depreciación vs USD desde 2020.</span>
            </div>
        </div>
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Wallet, Plus, Trash2, PieChart } from 'lucide-react';
import { useDashboardData } from '../hooks/useDashboardData';
import { formatInt, formatPct } from '../utils/formatARS';

interface PortfolioItem {
    id: string;
    asset: 'ARS' | 'USD' | 'USDT' | 'BTC' | 'ETH';
    amount: number;
}

export const PortfolioManager: React.FC = () => {
    const { arbitrage, rate, cryptoExtended } = useDashboardData();
    const [items, setItems] = useState<PortfolioItem[]>([]);
    const [isClient, setIsClient] = useState(false);

    // Initial Load
    useEffect(() => {
        setIsClient(true);
        const saved = localStorage.getItem('rulos-portfolio');
        if (saved) {
            try { setItems(JSON.parse(saved)); } catch (e) { }
        } else {
            setItems([{ id: '1', asset: 'ARS', amount: 500000 }, { id: '2', asset: 'USD', amount: 1000 }]);
        }
    }, []);

    // Save on change
    useEffect(() => {
        if (isClient) {
            localStorage.setItem('rulos-portfolio', JSON.stringify(items));
        }
    }, [items, isClient]);

    const { totalARS, totalUSD, assetBreakdown } = useMemo(() => {
        const cclRate = arbitrage?.dolares?.ccl?.venta || 1000;
        const usdtRate = rate?.ask || cclRate;
        const btcUsd = cryptoExtended?.bitcoin?.usd || 65000;
        const ethUsd = cryptoExtended?.ethereum?.usd || 3500;

        let ars = 0;
        let usd = 0;

        const breakdown: Record<string, { ars: number, usd: number, pct: number, color: string }> = {
            'ARS': { ars: 0, usd: 0, pct: 0, color: 'bg-indigo-500' },
            'USD': { ars: 0, usd: 0, pct: 0, color: 'bg-emerald-500' },
            'USDT': { ars: 0, usd: 0, pct: 0, color: 'bg-teal-400' },
            'BTC': { ars: 0, usd: 0, pct: 0, color: 'bg-orange-500' },
            'ETH': { ars: 0, usd: 0, pct: 0, color: 'bg-blue-500' },
        };

        items.forEach(item => {
            let itemArs = 0;
            let itemUsd = 0;

            if (item.asset === 'ARS') {
                itemArs = item.amount;
                itemUsd = item.amount / cclRate;
            } else if (item.asset === 'USD') {
                itemArs = item.amount * cclRate; // valuing at CCL
                itemUsd = item.amount;
            } else if (item.asset === 'USDT') {
                itemArs = item.amount * usdtRate;
                itemUsd = item.amount;
            } else if (item.asset === 'BTC') {
                itemUsd = item.amount * btcUsd;
                itemArs = itemUsd * cclRate;
            } else if (item.asset === 'ETH') {
                itemUsd = item.amount * ethUsd;
                itemArs = itemUsd * cclRate;
            }

            ars += itemArs;
            usd += itemUsd;
            breakdown[item.asset].ars += itemArs;
            breakdown[item.asset].usd += itemUsd;
        });

        // Calculate %
        if (ars > 0) {
            Object.keys(breakdown).forEach(k => {
                breakdown[k].pct = (breakdown[k].ars / ars) * 100;
            });
        }

        return { totalARS: ars, totalUSD: usd, assetBreakdown: breakdown };
    }, [items, arbitrage, rate, cryptoExtended]);

    const addItem = (asset: PortfolioItem['asset']) => {
        setItems(prev => [...prev, { id: Date.now().toString(), asset, amount: 0 }]);
    };

    const updateAmount = (id: string, amount: number) => {
        setItems(prev => prev.map(item => item.id === id ? { ...item, amount } : item));
    };

    const removeItem = (id: string) => {
        setItems(prev => prev.filter(item => item.id !== id));
    };

    if (!isClient) return null;

    return (
        <div className="bg-slate-800/50 rounded-2xl p-5 border border-slate-700/50 flex flex-col h-full col-span-1 lg:col-span-2">
            <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-500/20 text-indigo-400 rounded-xl">
                        <Wallet size={20} />
                    </div>
                    <div>
                        <h3 className="font-semibold text-slate-100">Mi Billetera</h3>
                        <p className="text-xs text-slate-400">Valuación en tiempo real de tu cartera</p>
                    </div>
                </div>
                <div className="text-right">
                    <div className="text-2xl font-bold text-white">{formatInt(totalARS)}</div>
                    <div className="text-xs font-medium text-emerald-400">USD {formatInt(totalUSD).replace('$', '')} al CCL</div>
                </div>
            </div>

            <div className="flex flex-col lg:flex-row gap-6">
                {/* Formulario */}
                <div className="flex-1 space-y-3">
                    {items.map((item) => (
                        <div key={item.id} className="flex items-center gap-2 bg-slate-900/50 p-2 rounded-xl border border-slate-700/50">
                            <div className={`w-2 h-8 rounded-full ${assetBreakdown[item.asset].color}`}></div>
                            <span className="font-bold text-slate-200 w-12">{item.asset}</span>
                            <input
                                type="number"
                                value={item.amount === 0 ? '' : item.amount}
                                onChange={(e) => updateAmount(item.id, Number(e.target.value))}
                                placeholder="0.00"
                                className="flex-1 bg-transparent border-none text-right font-medium text-white focus:outline-none focus:ring-0 placeholder-slate-600"
                            />
                            <button onClick={() => removeItem(item.id)} className="p-2 text-slate-500 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-colors">
                                <Trash2 size={16} />
                            </button>
                        </div>
                    ))}

                    <div className="flex gap-2 mt-2 flex-wrap">
                        {['ARS', 'USD', 'USDT', 'BTC', 'ETH'].map(asset => (
                            <button
                                key={asset}
                                onClick={() => addItem(asset as any)}
                                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium text-slate-300 bg-slate-700/50 hover:bg-slate-700 hover:text-white transition-colors border border-slate-600/50"
                            >
                                <Plus size={12} /> {asset}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Gráfico de composición */}
                <div className="w-full lg:w-64 flex flex-col items-center justify-center p-4 bg-slate-900/30 rounded-xl border border-slate-700/30">
                    <div className="flex items-center gap-2 mb-4 text-slate-300 font-medium text-sm w-full">
                        <PieChart size={16} /> Composición
                    </div>
                    {totalARS > 0 ? (
                        <div className="w-full space-y-2">
                            {Object.entries(assetBreakdown)
                                .filter(([, data]) => data.pct > 0)
                                .sort((a, b) => b[1].pct - a[1].pct)
                                .map(([asset, data]) => (
                                    <div key={asset}>
                                        <div className="flex justify-between text-xs mb-1">
                                            <span className="text-slate-200 font-bold">{asset}</span>
                                            <span className="text-slate-400">{data.pct.toFixed(1)}%</span>
                                        </div>
                                        <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                            <div className={`h-full ${data.color}`} style={{ width: `${data.pct}%` }}></div>
                                        </div>
                                    </div>
                                ))}
                        </div>
                    ) : (
                        <div className="text-xs text-slate-500 text-center py-8">
                            Añadí balances para ver tu composición
                        </div>
                    )}
                </div>
            </div>
            <p className="text-[10px] text-slate-500 mt-4 text-center">
                * Los activos se valúan usando Dólar CCL y precios en vivo de CoinGecko. Guardado localmente en tu navegador.
            </p>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { LineChart, TrendingUp } from 'lucide-react';

interface DataSeries {
